from rdkit import Chem

base = "COC(=O)C1=C2Nc3ccccc3C25CCCN4C5CC1C(C4)C(O)C"
# chiral centers: A=13, Cj=18, L3=20, L2=21, X=23
targets = {13:'R', 18:'S', 20:'S', 21:'S', 23:'S'}

m = Chem.MolFromSmiles(base)
# start: set all to '@'
tags = {i: Chem.ChiralType.CHI_TETRAHEDRAL_CCW for i in targets}
for i,t in tags.items():
    m.GetAtomWithIdx(i).SetChiralTag(t)

def get_cips(mol):
    smi = Chem.MolToSmiles(mol)
    mm = Chem.MolFromSmiles(smi)
    Chem.AssignStereochemistry(mm, cleanIt=True, force=True)
    cips = {}
    for a in mm.GetAtoms():
        if a.hasProp('_CIPCode'):
            cips[a.GetIdx()] = a.GetProp('_CIPCode')
    return smi, cips

for iteration in range(4):
    smi, cips = get_cips(m)
    print(f"iter {iteration}: CIPs = {cips}")
    if all(cips.get(k)==v for k,v in targets.items()):
        print("MATCH!", smi)
        break
    # flip those that are wrong
    for k,v in targets.items():
        if cips.get(k)!=v:
            a = m.GetAtomWithIdx(k)
            cur = a.GetChiralTag()
            a.SetChiralTag(Chem.ChiralType.CHI_TETRAHEDRAL_CW if cur==Chem.ChiralType.CHI_TETRAHEDRAL_CCW else Chem.ChiralType.CHI_TETRAHEDRAL_CCW)

smi, cips = get_cips(m)
print("final SMILES:", smi)
print("final CIPs:", cips)
