    Chem.AssignStereochemistry(mol, cleanIt=True, force=True)
    return {a.GetIdx(): a.GetProp('_CIPCode') for a in mol.GetAtoms() if a.HasProp('_CIPCode')}

for it in range(6):
    c = cips(m)
    status = {k: (c.get(k), v) for k,v in targets.items()}
    print(f"iter {it}: {status}")
    if all(c.get(k)==v for k,v in targets.items()):
        print("MATCH")
        break
    for k,v in targets.items():
        if c.get(k)!=v:
            a = m.GetAtomWithIdx(k)
            cur = a.GetChiralTag()
            a.SetChiralTag(Chem.ChiralType.CHI_TETRAHEDRAL_CW if cur==Chem.ChiralType.CHI_TETRAHEDRAL_CCW else Chem.ChiralType.CHI_TETRAHEDRAL_CCW)

print("final:", cips(m))
print(Chem.MolToSmiles(m))
