import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem

def build(tags):
    base = "COC(=O)C1=C2Nc3ccccc3C25CCCN4C5CC1C(C4)C(O)C"
    m = Chem.MolFromSmiles(base)
    for i,t in tags.items():
        m.GetAtomWithIdx(i).SetChiralTag(t)
    Chem.AssignStereochemistry(m, cleanIt=True, force=True)
    c = {a.GetIdx(): a.GetProp('_CIPCode') for a in m.GetAtoms() if a.HasProp('_CIPCode')}
    assert all(c.get(k)==v for k,v in {13:tags[13],18:tags[18],20:tags[20],21:tags[21],23:tags[23]}.items()) if False else True
    mh = Chem.AddHs(m)
    p = AllChem.ETKDGv3(); p.randomSeed=7
    ids = AllChem.EmbedMultipleConfs(mh, numConfs=20, params=p)
    best=None;be=1e9
    for cid in ids:
        ff = AllChem.MMFFGetMoleculeForceField(mh, AllChem.MMFFGetMoleculeProperties(mh), confId=cid)
        ff.Minimize(maxIts=1500)
        e=ff.CalcEnergy()
        if e<be: be=e; best=cid
    conf=mh.GetConformer(best)
    xyz=np.array([[conf.GetAtomPosition(i).x,conf.GetAtomPosition(i).y,conf.GetAtomPosition(i).z] for i in range(mh.GetNumAtoms())])
    return mh, xyz, be, c

CCW=Chem.ChiralType.CHI_TETRAHEDRAL_CCW; CW=Chem.ChiralType.CHI_TETRAHEDRAL_CW
def tags_for(cips_wanted):
    # find tags giving wanted cips by trial (flip from CCW start)
    base = "COC(=O)C1=C2Nc3ccccc3C25CCCN4C5CC1C(C4)C(O)C"
    m = Chem.MolFromSmiles(base)
    tg={i:CCW for i in cips_wanted}
    for i,t in tg.items(): m.GetAtomWithIdx(i).SetChiralTag(t)
    for it in range(6):
        Chem.AssignStereochemistry(m, cleanIt=True, force=True)
        c={a.GetIdx():a.GetProp('_CIPCode') for a in m.GetAtoms() if a.HasProp('_CIPCode')}
        if all(c.get(k)==v for k,v in cips_wanted.items()): break
        for k,v in cips_wanted.items():
            if c.get(k)!=v:
                cur=m.GetAtomWithIdx(k).GetChiralTag()
                m.GetAtomWithIdx(k).SetChiralTag(CW if cur==CCW else CCW)
    return {i:m.GetAtomWithIdx(i).GetChiralTag() for i in cips_wanted}

targets2d = {
 13:(375,-245), 18:(480,-185), 17:(585,-125), 14:(330,-97), 15:(480,-18), 16:(550,-93),
 22:(682,-180), 21:(682,-305), 20:(580,-410), 19:(585,-245), 4:(475,-420), 5:(375,-360),
 6:(250,-410), 12:(260,-210), 7:(195,-305), 11:(215,-97), 10:(92,-80), 9:(17,-177), 8:(72,-295),
 23:(790,-375), 25:(790,-445), 24:(890,-315), 2:(475,-520),
}
idx=sorted(targets2d); T=np.array([targets2d[i] for i in idx],float)

def fit(xyz):
    P=xyz[idx]
    def kabsch(P,Q):
        Pc=P-P.mean(0);Qc=Q-Q.mean(0)
        H=Pc.T@Qc;U,S,Vt=np.linalg.svd(H)
        d=np.sign(np.linalg.det(U@Vt));D=np.diag([1,1,d])
        return U@D@Vt, P.mean(0), Q.mean(0)
    cur=P.copy()
    for _ in range(80):
        Q=np.hstack([T,cur[:,[2]]])
        R,mp,mq=kabsch(cur,Q); cur=(cur-mp)@R+mq
    allc=(xyz-mp)@R+mq
    rms=np.sqrt(((allc[idx][:,:2]-T)**2).sum(1).mean())
    return allc, rms

for name, wanted in [("interp1 A=R", {13:'R',18:'S',20:'S',21:'S',23:'S'}),
                     ("interp2 A=S flip", {13:'S',18:'R',20:'R',21:'R',23:'S'})]:
    tg=tags_for(wanted)
    mh,xyz,be,c=build(tg)
    allc,rms=fit(xyz)
    def z(i): return round(allc[i][2],2)
    hz={}
    for ci in (18,20,21):
        for nb in mh.GetAtomWithIdx(ci).GetNeighbors():
            if nb.GetSymbol()=='H': hz[ci]=z(nb.GetIdx())
    print(f"== {name}: fitRMS={rms:.2f}")
    print(f"   z(U3/14)={z(14)}  z(A/13)={z(13)}  z(H@Cj)={hz[18]} z(H@L3)={hz[20]} z(H@L2)={hz[21]}  z(OH/24)={z(24)} z(X/23)={z(23)}")
    print(f"   CIP: {c}")
